<section>
    <p class="eyebrow">Equipe</p><h1>Responsaveis · <?= App\Core\View::e($team['name']) ?></h1>
    <?php foreach (($errors ?? []) as $error): ?><p class="alert" role="alert"><?= App\Core\View::e($error) ?></p><?php endforeach; ?>
    <?php if ($canManage): ?><form method="post" action="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'] . '/responsaveis')) ?>" class="inline-form"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><label>Usuario <select name="user_id" required><option value="">Selecione</option><?php foreach ($candidates as $candidate): ?><option value="<?= (int) $candidate['id'] ?>"><?= App\Core\View::e($candidate['name']) ?> · <?= App\Core\View::e($candidate['email']) ?></option><?php endforeach; ?></select></label><label>Vinculo <select name="assignment_type"><option value="head_coach">Treinador</option><option value="manager">Gestor</option><option value="assistant_coach">Auxiliar</option><option value="viewer">Consulta</option></select></label><label>Inicio <input type="date" name="starts_at" value="<?= date('Y-m-d') ?>"></label><button type="submit">Vincular</button></form><?php endif; ?>
    <div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Tipo</th><th>Status</th><th>Periodo</th><th>Acoes</th></tr></thead><tbody><?php foreach ($assignments as $assignment): ?><tr><td><?= App\Core\View::e($assignment['name']) ?><br><small><?= App\Core\View::e($assignment['email']) ?></small></td><td><?= App\Core\View::e($assignment['assignment_type']) ?></td><td><?= App\Core\View::e($assignment['status']) ?></td><td><?= App\Core\View::e($assignment['starts_at']) ?><?= $assignment['ends_at'] ? ' a ' . App\Core\View::e($assignment['ends_at']) : '' ?></td><td><?php if ($canManage && $assignment['status'] === 'active'): ?><form method="post" action="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'] . '/responsaveis/' . $assignment['id'] . '/encerrar')) ?>"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><button type="submit">Encerrar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
    <p><a href="<?= App\Core\View::e(App\Core\Config::url('/admin/equipes/' . $team['slug'])) ?>">Voltar para equipe</a></p>
</section>
